{"code": "import json

from fastapi import Depends, FastAPI, Request, status
from fastapi.responses import JSONResponse
from pydantic import BaseModel


class Config(BaseModel):
    PAGE_SIZE: int = 3
    FEATURE_VERBOSE: bool = True
    SERVICE_NAME: str = "reporting"
    MAX_RANGE_DAYS: int = 30


app = FastAPI()
app.state.config = Config()

_ROWS = [{"id": i, "value": i * 10} for i in range(1, 11)]


def get_config(request: Request) -> Config:
    return request.app.state.config


@app.get("/config")
def show_config(config: Config = Depends(get_config)) -> JSONResponse:
    return JSONResponse(
        {
            "service": config.SERVICE_NAME,
            "page_size": config.PAGE_SIZE,
            "verbose": config.FEATURE_VERBOSE,
        }
    )


@app.get("/rows")
async def rows(request: Request, config: Config = Depends(get_config)) -> JSONResponse:
    size_raw = request.query_params.get("size")
    try:
        size = int(size_raw) if size_raw is not None else None
    except ValueError:
        size = None
    if not size:
        size = config.PAGE_SIZE

    page = _ROWS[:size]
    payload = {"rows": page}
    if config.FEATURE_VERBOSE:
        payload["meta"] = {"returned": len(page), "total": len(_ROWS)}
    return JSONResponse(payload)


@app.post("/report")
async def report(request: Request, config: Config = Depends(get_config)) -> JSONResponse:
    content_type = request.headers.get("content-type", "").split(";")[0].strip().lower()
    is_json = content_type == "application/json" or content_type.endswith("+json")
    data = {}
    if is_json:
        raw = await request.body()
        if raw:
            try:
                data = json.loads(raw) or {}
            except (json.JSONDecodeError, UnicodeDecodeError):
                data = {}

    days = data.get("days", 7)
    if not isinstance(days, int):
        return JSONResponse({"error": "days must be an integer"}, status_code=400)
    if days > config.MAX_RANGE_DAYS:
        return JSONResponse(
            {"error": "range too large", "max": config.MAX_RANGE_DAYS},
            status_code=400,
        )
    return JSONResponse(
        {"service": config.SERVICE_NAME, "days": days},
        status_code=status.HTTP_202_ACCEPTED,
    )
"}

{"code": "from typing import Any, Dict, Optional

from fastapi import Depends, FastAPI, Header, HTTPException, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel

_TOKENS = {"secret-token": {"user": "ana", "role": "admin"}}
_NOTES = {1: {"id": 1, "owner": "ana", "text": "first"}}


class IdentityOut(BaseModel):
    user: str
    role: str


class NoteOut(BaseModel):
    id: int
    owner: str
    text: Any


app = FastAPI()


@app.exception_handler(HTTPException)
async def http_exception_handler(request: Request, exc: HTTPException):
    if isinstance(exc.detail, dict):
        content = exc.detail
    else:
        content = {"detail": exc.detail}
    return JSONResponse(status_code=exc.status_code, content=content)


def authenticate(x_api_token: Optional[str] = Header(default=None, alias="X-Api-Token")) -> Dict[str, str]:
    if not x_api_token:
        raise HTTPException(status_code=401, detail={"error": "missing token", "code": "AUTH_001"})
    identity = _TOKENS.get(x_api_token)
    if identity is None:
        raise HTTPException(status_code=401, detail={"error": "invalid token", "code": "AUTH_002"})
    return identity


@app.get("/api/v1/whoami", response_model=IdentityOut)
def whoami(identity: Dict[str, str] = Depends(authenticate)):
    return {"user": identity["user"], "role": identity["role"]}


@app.get("/api/v1/notes/{note_id}", response_model=NoteOut)
def get_note(note_id: int, identity: Dict[str, str] = Depends(authenticate)):
    note = _NOTES.get(note_id)
    if note is None:
        raise HTTPException(status_code=404, detail="Not Found")
    if note["owner"] != identity["user"]:
        raise HTTPException(status_code=403, detail={"error": "forbidden"})
    return note


@app.post("/api/v1/notes", response_model=NoteOut, status_code=201)
async def create_note(request: Request, identity: Dict[str, str] = Depends(authenticate)):
    try:
        data = await request.json()
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}
    text = data.get("text")
    if not text:
        raise HTTPException(status_code=422, detail={"error": "text is required", "code": "VAL_001"})
    return {"id": 2, "owner": identity["user"], "text": text}
"}

{"code":""""Query-string heavy search endpoint. Synthetic case for this benchmark.

Exercises: typed query parameters with defaults, getlist for repeated values,
a truthy-string boolean, and silent coercion failures.
"""

from typing import Dict, List, Optional

from fastapi import FastAPI, Query
from pydantic import BaseModel
import uvicorn

app = FastAPI()

_PRODUCTS = [
    {"id": 1, "name": "bolt", "tag": "hardware", "price": 3},
    {"id": 2, "name": "nut", "tag": "hardware", "price": 1},
    {"id": 3, "name": "manual", "tag": "docs", "price": 0},
]


class Product(BaseModel):
    id: int
    name: str
    tag: str
    price: int


class Echo(BaseModel):
    q: str
    limit: Optional[int]


class SearchResponse(BaseModel):
    results: List[Product]
    count: int
    echo: Echo


class FacetsResponse(BaseModel):
    tags: Dict[str, int]


def _parse_int(value: Optional[str]) -> Optional[int]:
    if value is None:
        return None
    try:
        return int(value)
    except ValueError:
        return None


def _parse_float(value: Optional[str]) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except ValueError:
        return None


@app.get("/search", response_model=SearchResponse)
def search(
    q: str = "",
    limit: Optional[str] = Query(default=None),
    max_price: Optional[str] = Query(default=None),
    include_free: str = "false",
    tag: List[str] = Query(default=[]),
):
    term = q
    limit_value = _parse_int(limit)
    max_price_value = _parse_float(max_price)
    include_free_value = include_free.lower() in ("1", "true", "yes")
    tags = tag

    rows = [p for p in _PRODUCTS if term.lower() in p["name"].lower()]
    if tags:
        rows = [p for p in rows if p["tag"] in tags]
    if max_price_value is not None:
        rows = [p for p in rows if p["price"] <= max_price_value]
    if not include_free_value:
        rows = [p for p in rows if p["price"] > 0]
    if limit_value:
        rows = rows[:limit_value]

    return {
        "results": rows,
        "count": len(rows),
        "echo": {"q": term, "limit": limit_value},
    }


@app.get("/facets", response_model=FacetsResponse)
def facets():
    counts = {}
    for product in _PRODUCTS:
        counts[product["tag"]] = counts.get(product["tag"], 0) + 1
    return {"tags": counts}


if __name__ == "__main__":
    uvicorn.run(app, host="127.0.0.1", port=8000)
"}"

{"code": "import json

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from starlette.exceptions import HTTPException as StarletteHTTPException
from pydantic import BaseModel

app = FastAPI()

_ACCOUNTS = {"a1": {"id": "a1", "balance": 100}}


class Account(BaseModel):
    id: str
    balance: int


class InsufficientFunds(Exception):
    def __init__(self, needed, available):
        super().__init__("insufficient funds")
        self.needed = needed
        self.available = available


@app.exception_handler(InsufficientFunds)
async def on_insufficient_funds(request: Request, exc: InsufficientFunds):
    return JSONResponse(
        status_code=409,
        content={"error": "insufficient_funds", "needed": exc.needed, "available": exc.available},
    )


@app.exception_handler(StarletteHTTPException)
async def on_http_error(request: Request, exc: StarletteHTTPException):
    return JSONResponse(
        status_code=exc.status_code,
        content={"error": "http_error", "status": exc.status_code, "message": exc.detail},
    )


@app.get("/accounts/{account_id}", response_model=Account)
async def get_account(account_id: str):
    account = _ACCOUNTS.get(account_id)
    if account is None:
        return JSONResponse(status_code=404, content={"error": "not_found", "resource": "account"})
    return account


@app.post("/accounts/{account_id}/withdraw")
async def withdraw(account_id: str, request: Request):
    account = _ACCOUNTS.get(account_id)
    if account is None:
        return JSONResponse(status_code=404, content={"error": "not_found", "resource": "account"})

    data = {}
    content_type = request.headers.get("content-type", "").lower()
    if content_type.startswith("application/json"):
        body = await request.body()
        if body:
            try:
                data = json.loads(body) or {}
            except json.JSONDecodeError:
                data = {}

    amount = data.get("amount")
    if not isinstance(amount, int) or amount <= 0:
        return JSONResponse(status_code=400, content={"error": "bad_amount"})

    if amount > account["balance"]:
        raise InsufficientFunds(amount, account["balance"])

    return {"id": account_id, "withdrawn": amount, "balance": account["balance"] - amount}
"}

{"code":""""Small inventory service. Migrated from Flask to FastAPI.

Exercises: JSON body handling, manual validation with explicit 400s, a query
parameter with a default, path converters, and 404 on a missing resource.
"""

from typing import Any, Optional

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ValidationError

import json

app = FastAPI()

PAGE_SIZE = 2

_ITEMS = {
    1: {"id": 1, "name": "bolt", "qty": 40},
    2: {"id": 2, "name": "nut", "qty": 12},
    3: {"id": 3, "name": "washer", "qty": 7},
}


class Item(BaseModel):
    id: int
    name: str
    qty: Any


class ItemCreate(BaseModel):
    name: str
    qty: Any = 0


@app.get("/items")
def list_items(limit: Optional[str] = None):
    if limit is None:
        resolved_limit = PAGE_SIZE
    else:
        try:
            resolved_limit = int(limit)
        except ValueError:
            resolved_limit = PAGE_SIZE
        if not resolved_limit:
            resolved_limit = PAGE_SIZE
    items = list(_ITEMS.values())[:resolved_limit]
    return {"items": items, "count": len(items)}


@app.get("/items/{item_id}")
def get_item(item_id: int):
    item = _ITEMS.get(item_id)
    if item is None:
        return JSONResponse(status_code=404, content={"error": "item not found"})
    return JSONResponse(status_code=200, content=item)


@app.post("/items")
async def create_item(request: Request):
    try:
        payload = await request.json()
    except (json.JSONDecodeError, ValueError):
        return JSONResponse(status_code=400, content={"error": "body must be JSON"})

    if not payload:
        return JSONResponse(status_code=400, content={"error": "body must be JSON"})

    if not isinstance(payload, dict):
        return JSONResponse(status_code=400, content={"error": "name is required"})

    try:
        item_data = ItemCreate.model_validate(payload)
    except ValidationError as exc:
        for err in exc.errors():
            if err["loc"] == ("name",) and err["type"] == "missing":
                return JSONResponse(status_code=400, content={"error": "name is required"})
            if err["loc"] == ("name",) and err["type"] == "string_type":
                return JSONResponse(status_code=400, content={"error": "name must be a string"})
        return JSONResponse(status_code=400, content={"error": "invalid payload"})

    new_id = max(_ITEMS) + 1
    return JSONResponse(
        status_code=201,
        content={"id": new_id, "name": item_data.name, "qty": item_data.qty},
    )


@app.delete("/items/{item_id}")
def delete_item(item_id: int):
    if item_id not in _ITEMS:
        return JSONResponse(status_code=404, content={"error": "item not found"})
    return {"deleted": item_id}


@app.get("/health")
def health():
    return {"status": "ok", "page_size": PAGE_SIZE}
"}

