{"code":"'''Order lifecycle with idempotency. Synthetic case for this benchmark.

Behaviour that lives in the handler rather than in the schema, which is exactly
the kind a type-driven rewrite loses:

  * an Idempotency-Key header makes a repeated create return the *original*
    resource with 200 instead of 201, and a reused key with a different body is
    a 422 with a specific code
  * transitions are validated against a table; an illegal one is a 409 that
    lists what would have been legal
  * delete is only allowed from draft; anywhere else is 409, not 405
  * the response carries a computed field that is not stored anywhere
  * an unknown transition target is 400, while a known-but-illegal one is 409 --
    two different statuses for what looks like the same mistake
'''

from typing import Any, List, Optional

import uvicorn
from fastapi import FastAPI, Header, Query, Request, Response
from fastapi.responses import JSONResponse
from pydantic import BaseModel

app = FastAPI()

TRANSITIONS = {
    'draft': ['submitted', 'cancelled'],
    'submitted': ['approved', 'rejected', 'cancelled'],
    'approved': ['fulfilled'],
    'rejected': [],
    'cancelled': [],
    'fulfilled': [],
}
TERMINAL = {'rejected', 'cancelled', 'fulfilled'}

_ORDERS = {
    'o1': {'id': 'o1', 'state': 'draft', 'total': 30, 'lines': 2},
    'o2': {'id': 'o2', 'state': 'approved', 'total': 90, 'lines': 5},
}
_IDEMPOTENCY = {}
_NEXT = [3]


def _present(order):
    return {**order, 'terminal': order['state'] in TERMINAL}


class OrderResponse(BaseModel):
    id: str
    state: str
    total: Any
    lines: Any
    terminal: bool


class OrderListResponse(BaseModel):
    orders: List[OrderResponse]
    count: int


@app.get('/orders/{order_id}', response_model=OrderResponse)
async def get_order(order_id: str):
    order = _ORDERS.get(order_id)
    if order is None:
        return JSONResponse(status_code=404, content={'error': 'order not found', 'id': order_id})
    return _present(order)


@app.post('/orders', response_model=OrderResponse)
async def create_order(
    request: Request,
    response: Response,
    idempotency_key: Optional[str] = Header(default=None, alias='Idempotency-Key'),
):
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not body:
        body = {}
    total = body.get('total')
    if not isinstance(total, int) or total <= 0:
        return JSONResponse(
            status_code=400,
            content={'error': 'total must be a positive integer'},
        )

    key = idempotency_key
    if key:
        seen = _IDEMPOTENCY.get(key)
        if seen is not None:
            if seen['total'] != total:
                return JSONResponse(
                    status_code=422,
                    content={
                        'error': 'idempotency key reused with a different body',
                        'code': 'IDEMPOTENCY_MISMATCH',
                    },
                )
            # Replay: the original resource, and 200 rather than 201.
            return _present(_ORDERS[seen['id']])

    order_id = f'o{_NEXT[0]}'
    _NEXT[0] += 1
    order = {
        'id': order_id,
        'state': 'draft',
        'total': total,
        'lines': body.get('lines', 1),
    }
    _ORDERS[order_id] = order
    if key:
        _IDEMPOTENCY[key] = {'id': order_id, 'total': total}

    response.status_code = 201
    response.headers['Location'] = f'/orders/{order_id}'
    return _present(order)


@app.post('/orders/{order_id}/transition', response_model=OrderResponse)
async def transition_order(request: Request, order_id: str):
    order = _ORDERS.get(order_id)
    if order is None:
        return JSONResponse(status_code=404, content={'error': 'order not found', 'id': order_id})

    try:
        body = await request.json()
    except Exception:
        body = {}
    if not body:
        body = {}
    target = body.get('to')
    if not target:
        return JSONResponse(status_code=400, content={'error': 'to is required'})
    if target not in TRANSITIONS:
        return JSONResponse(status_code=400, content={'error': 'unknown state', 'state': target})

    allowed = TRANSITIONS[order['state']]
    if target not in allowed:
        return JSONResponse(
            status_code=409,
            content={
                'error': 'illegal transition',
                'from': order['state'],
                'to': target,
                'allowed': allowed,
            },
        )

    order['state'] = target
    return _present(order)


@app.delete('/orders/{order_id}')
async def delete_order(order_id: str):
    order = _ORDERS.get(order_id)
    if order is None:
        return JSONResponse(status_code=404, content={'error': 'order not found', 'id': order_id})
    if order['state'] != 'draft':
        return JSONResponse(
            status_code=409,
            content={
                'error': 'only draft orders can be deleted',
                'state': order['state'],
                'code': 'NOT_DELETABLE',
            },
        )
    return Response(status_code=204)


@app.get('/orders', response_model=OrderListResponse)
async def list_orders(state: Optional[str] = Query(default=None)):
    rows = list(_ORDERS.values())
    if state:
        if state not in TRANSITIONS:
            return JSONResponse(status_code=400, content={'error': 'unknown state', 'state': state})
        rows = [o for o in rows if o['state'] == state]
    return {'orders': [_present(o) for o in rows], 'count': len(rows)}


if __name__ == '__main__':
    uvicorn.run(app, host='0.0.0.0', port=8000)
"}

{"code": """"Small inventory service. Synthetic case, written for this benchmark.

Exercises: JSON body handling, manual validation with explicit 400s, a query
parameter with a default, path converters, and 404 on a missing resource.
"""

from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse, JSONResponse
from starlette.exceptions import HTTPException as StarletteHTTPException

app = FastAPI(docs_url=None, redoc_url=None, openapi_url=None)

PAGE_SIZE = 2

_ITEMS = {
    1: {"id": 1, "name": "bolt", "qty": 40},
    2: {"id": 2, "name": "nut", "qty": 12},
    3: {"id": 3, "name": "washer", "qty": 7},
}

FLASK_404_BODY = (
    '<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 3.2 Final//EN">\n'
    "<title>Not Found</title>\n"
    "<h1>Not Found</h1>\n"
    "<p>The requested URL was not found on the server. If you entered the URL "
    "manually please check your spelling and try again.</p>"
)

FLASK_405_BODY = (
    '<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 3.2 Final//EN">\n'
    "<title>Method Not Allowed</title>\n"
    "<h1>Method Not Allowed</h1>\n"
    "<p>The method is not allowed for the requested URL.</p>"
)


@app.exception_handler(StarletteHTTPException)
async def http_exception_handler(request: Request, exc: StarletteHTTPException):
    if exc.status_code == 404:
        return HTMLResponse(content=FLASK_404_BODY, status_code=404)
    if exc.status_code == 405:
        return HTMLResponse(content=FLASK_405_BODY, status_code=405)
    return JSONResponse(status_code=exc.status_code, content={"detail": exc.detail})


def _parse_limit(request: Request) -> int:
    raw = request.query_params.get("limit")
    if raw is None:
        return PAGE_SIZE
    try:
        limit = int(raw)
    except (TypeError, ValueError):
        limit = None
    if not limit:
        return PAGE_SIZE
    return limit


@app.get("/health")
def health():
    return JSONResponse({"status": "ok", "page_size": PAGE_SIZE})


@app.get("/items")
def list_items(request: Request):
    limit = _parse_limit(request)
    items = list(_ITEMS.values())[:limit]
    return JSONResponse({"items": items, "count": len(items)})


@app.get("/items/{item_id:int}")
def get_item(item_id: int):
    item = _ITEMS.get(item_id)
    if item is None:
        return JSONResponse({"error": "item not found"}, status_code=404)
    return JSONResponse(item)


@app.post("/items")
async def create_item(request: Request):
    content_type = request.headers.get("content-type")
    if content_type is None:
        data = None
    else:
        mimetype = content_type.split(";")[0].strip().lower()
        if mimetype != "application/json" and not (
            mimetype.startswith("application/") and mimetype.endswith("+json")
        ):
            data = None
        else:
            try:
                data = await request.json()
            except Exception:
                data = None

    if not data:
        return JSONResponse({"error": "body must be JSON"}, status_code=400)
    if "name" not in data:
        return JSONResponse({"error": "name is required"}, status_code=400)
    if not isinstance(data["name"], str):
        return JSONResponse({"error": "name must be a string"}, status_code=400)
    qty = data.get("qty", 0)
    new_id = max(_ITEMS) + 1
    return JSONResponse(
        {"id": new_id, "name": data["name"], "qty": qty}, status_code=201
    )


@app.delete("/items/{item_id:int}")
def delete_item(item_id: int):
    if item_id not in _ITEMS:
        return JSONResponse({"error": "item not found"}, status_code=404)
    return JSONResponse({"deleted": item_id})
"}"}

{"code": "import json
from pydantic import BaseModel, ConfigDict
from fastapi import APIRouter, Depends, FastAPI, Request
from fastapi.responses import HTMLResponse, JSONResponse
from starlette.exceptions import HTTPException as StarletteHTTPException


class Identity(BaseModel):
    model_config = ConfigDict(extra='forbid')
    user: str
    role: str


class AuthError(Exception):
    def __init__(self, body):
        super().__init__()
        self.body = body


class FlaskJSONResponse(JSONResponse):
    charset = None

    def render(self, content):
        return json.dumps(
            content,
            sort_keys=True,
            separators=(',', ':'),
            ensure_ascii=False,
        ).encode('utf-8') + bytes([10])


_TOKENS = {'secret-token': {'user': 'ana', 'role': 'admin'}}
_NOTES = {1: {'id': 1, 'owner': 'ana', 'text': 'first'}}

FLASK_404_BODY = chr(10).join([
    '<!doctype html>',
    '<html lang=en>',
    '<title>404 Not Found</title>',
    '<h1>Not Found</h1>',
    '<p>The requested URL was not found on the server. If you entered the URL manually please check your spelling and try again.</p>',
]) + chr(10)

FLASK_405_BODY = chr(10).join([
    '<!doctype html>',
    '<html lang=en>',
    '<title>405 Method Not Allowed</title>',
    '<h1>Method Not Allowed</h1>',
    '<p>The method is not allowed for the requested URL.</p>',
]) + chr(10)


def _is_json_content_type(value):
    media_type = value.split(';', 1)[0].strip().lower()
    return media_type == 'application/json' or (
        media_type.startswith('application/') and media_type.endswith('+json')
    )


def authenticate(request: Request):
    token = request.headers.get('X-Api-Token')
    if not token:
        raise AuthError({'error': 'missing token', 'code': 'AUTH_001'})
    identity_data = _TOKENS.get(token)
    if identity_data is None:
        raise AuthError({'error': 'invalid token', 'code': 'AUTH_002'})
    request.state.identity = Identity(**identity_data)


router = APIRouter(prefix='/api/v1', dependencies=[Depends(authenticate)])


@router.get('/whoami')
def whoami(request: Request):
    identity = request.state.identity
    return FlaskJSONResponse(
        content={'user': identity.user, 'role': identity.role},
        status_code=200,
    )


@router.get('/notes/{note_id:int}')
def get_note(request: Request, note_id: int):
    note = _NOTES.get(note_id)
    if note is None:
        return HTMLResponse(content=FLASK_404_BODY, status_code=404)
    if note['owner'] != request.state.identity.user:
        return FlaskJSONResponse(content={'error': 'forbidden'}, status_code=403)
    return FlaskJSONResponse(content=note, status_code=200)


@router.post('/notes')
async def create_note(request: Request):
    identity = request.state.identity
    raw = await request.body()
    if _is_json_content_type(request.headers.get('Content-Type', '')):
        try:
            data = json.loads(raw)
        except (json.JSONDecodeError, UnicodeDecodeError):
            data = None
        data = data or {}
    else:
        data = {}
    text = data.get('text')
    if not text:
        return FlaskJSONResponse(
            content={'error': 'text is required', 'code': 'VAL_001'},
            status_code=422,
        )
    return FlaskJSONResponse(
        content={'id': 2, 'owner': identity.user, 'text': text},
        status_code=201,
    )


app = FastAPI(docs_url=None, redoc_url=None, openapi_url=None)


@app.exception_handler(AuthError)
async def auth_error_handler(request: Request, exc: AuthError):
    return FlaskJSONResponse(content=exc.body, status_code=401)


@app.exception_handler(StarletteHTTPException)
async def http_exception_handler(request: Request, exc: StarletteHTTPException):
    if exc.status_code == 404:
        return HTMLResponse(content=FLASK_404_BODY, status_code=404)
    if exc.status_code == 405:
        return HTMLResponse(content=FLASK_405_BODY, status_code=405)
    return FlaskJSONResponse(content={'detail': exc.detail}, status_code=exc.status_code)


app.include_router(router)
"}

{"code": "from fastapi import FastAPI, Depends, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel

app = FastAPI()

class AppConfig(BaseModel):
    PAGE_SIZE: int = 3
    FEATURE_VERBOSE: bool = True
    SERVICE_NAME: str = "reporting"
    MAX_RANGE_DAYS: int = 30

_ROWS = [{"id": i, "value": i * 10} for i in range(1, 11)]

def get_config() -> AppConfig:
    return AppConfig()

def _is_json_content_type(request: Request) -> bool:
    content_type = request.headers.get("content-type", "").split(";")[0].strip().lower()
    return content_type == "application/json" or content_type.endswith("+json")

@app.get("/config")
def show_config(config: AppConfig = Depends(get_config)):
    return JSONResponse(content={
        "service": config.SERVICE_NAME,
        "page_size": config.PAGE_SIZE,
        "verbose": config.FEATURE_VERBOSE,
    })

@app.get("/rows")
def rows(request: Request, config: AppConfig = Depends(get_config)):
    size_raw = request.query_params.get("size")
    size = None
    if size_raw is not None:
        try:
            size = int(size_raw)
        except ValueError:
            size = None
    if not size:
        size = config.PAGE_SIZE
    page = _ROWS[:size]
    payload = {"rows": page}
    if config.FEATURE_VERBOSE:
        payload["meta"] = {"returned": len(page), "total": len(_ROWS)}
    return JSONResponse(content=payload)

@app.post("/report")
async def report(request: Request, config: AppConfig = Depends(get_config)):
    data = None
    if _is_json_content_type(request):
        try:
            data = await request.json()
        except Exception:
            data = None
    if not data:
        data = {}
    days = data.get("days", 7)
    if not isinstance(days, int):
        return JSONResponse(content={"error": "days must be an integer"}, status_code=400)
    if days > config.MAX_RANGE_DAYS:
        return JSONResponse(content={"error": "range too large", "max": config.MAX_RANGE_DAYS}, status_code=400)
    return JSONResponse(content={"service": config.SERVICE_NAME, "days": days}, status_code=202)
"}

{"code": "from fastapi import FastAPI, Query

app = FastAPI()

_PRODUCTS = [
    {"id": 1, "name": "bolt", "price": 3, "tag": "hardware"},
    {"id": 2, "name": "nut", "price": 1, "tag": "hardware"},
    {"id": 3, "name": "manual", "price": 0, "tag": "docs"},
]


@app.get("/search")
def search(
    q: str = Query(default=""),
    limit: str = Query(default=None),
    max_price: str = Query(default=None),
    include_free: str = Query(default="false"),
    tags: list[str] = Query(default=None, alias="tag"),
):
    term = q
    if tags is None:
        tags = []

    if limit is None:
        real_limit = None
    else:
        try:
            real_limit = int(limit)
        except ValueError:
            real_limit = None

    if max_price is None:
        real_max_price = None
    else:
        try:
            real_max_price = float(max_price)
        except ValueError:
            real_max_price = None

    include_free = include_free.lower() in ("1", "true", "yes")

    rows = [p for p in _PRODUCTS if term.lower() in p["name"].lower()]
    if tags:
        rows = [p for p in rows if p["tag"] in tags]
    if real_max_price is not None:
        rows = [p for p in rows if p["price"] <= real_max_price]
    if not include_free:
        rows = [p for p in rows if p["price"] > 0]
    if real_limit:
        rows = rows[:real_limit]

    return {
        "count": len(rows),
        "echo": {"limit": real_limit, "q": term},
