from typing import Any

from fastapi import FastAPI, Request, Depends
from fastapi.responses import JSONResponse, HTMLResponse
from starlette.exceptions import HTTPException as StarletteHTTPException

_TOKENS = {"secret-token": {"user": "ana", "role": "admin"}}
_NOTES = {1: {"id": 1, "owner": "ana", "text": "first"}}

FLASK_404_BODY = (
    "<!doctype html>\n"
    "<html lang=en>\n"
    "<title>404 Not Found</title>\n"
    "<h1>Not Found</h1>\n"
    "<p>The requested URL was not found on the server. If you entered the URL manually "
    "please check your spelling and try again.</p>\n"
)

class FlaskJSONResponse(JSONResponse):
    def render(self, content: Any) -> bytes:
        return json.dumps(
            content,
            ensure_ascii=False,
            indent=None,
            separators=(",", ":"),
            sort_keys=True,
        ).encode("utf-8")


class AuthError(Exception):
    def __init__(self, error: str, code: str):
        super().__init__(error)
        self.error = error
        self.code = code


app = FastAPI(docs_url=None, redoc_url=None, openapi_url=None)


@app.exception_handler(AuthError)
async def auth_error_handler(request: Request, exc: AuthError):
    return FlaskJSONResponse(status_code=401, content={"error": exc.error, "code": exc.code})


@app.exception_handler(StarletteHTTPException)
async def starlette_http_exception_handler(request: Request, exc: StarletteHTTPException):
    if exc.status_code == 404:
        return HTMLResponse(status_code=404, content=FLASK_404_BODY)
    return JSONResponse(status_code=exc.status_code, content={"detail": exc.detail})


async def require_auth(request: Request) -> dict:
    token = request.headers.get("X-Api-Token")
    if not token:
        raise AuthError("missing token", "AUTH_001")
    identity = _TOKENS.get(token)
    if identity is None:
        raise AuthError("invalid token", "AUTH_002")
    return identity


@app.post("/api/v1/notes", status_code=201)
async def create_note(request: Request, identity: dict = Depends(require_auth)):
    content_type = request.headers.get("content-type", "")
    mimetype = content_type.split(";")[0].strip().lower()
    data = {}
    if mimetype == "application/json" or mimetype.endswith("+json"):
        try:
            body = await request.json()
            if isinstance(body, dict):
                data = body
        except Exception:
            data = {}
    text = data.get("text") if isinstance(data, dict) else None
    if not text:
        return FlaskJSONResponse(status_code=422, content={"error": "text is required", "code": "VAL_001"})
    return FlaskJSONResponse(status_code=201, content={"id": 2, "owner": identity["user"], "text": text})


@app.get("/api/v1/notes/{note_id}")
async def get_note(note_id: int, identity: dict = Depends(require_auth)):
    note = _NOTES.get(note_id)
    if note is None:
        return HTMLResponse(status_code=404, content=FLASK_404_BODY)
    if note["owner"] != identity["user"]:
        return FlaskJSONResponse(status_code=403, content={"error": "forbidden"})
    return FlaskJSONResponse(content=note)


@app.get("/api/v1/whoami")
async def whoami(identity: dict = Depends(require_auth)):
    return FlaskJSONResponse(content={"user": identity["user"], "role": identity["role"]})
"}

{"code": "import json
import re
from fastapi import Depends, FastAPI, Request
from fastapi.responses import HTMLResponse, Response
from starlette.exceptions import HTTPException as StarletteHTTPException

PAGE_SIZE = 2

_ITEMS = {
    1: {"id": 1, "name": "bolt", "qty": 40},
    2: {"id": 2, "name": "nut", "qty": 12},
    3: {"id": 3, "name": "washer", "qty": 7},
}

_FLASK_404_HTML = (
    "<!doctype html>\n"
    "<html lang=en>\n"
    "<title>404 Not Found</title>\n"
    "<h1>Not Found</h1>\n"
    "<p>The requested URL was not found on the server. If you entered the URL manually "
    "please check your spelling and try again.</p>\n"
)

_FLASK_405_HTML = (
    "<!doctype html>\n"
    "<html lang=en>\n"
    "<title>405 Method Not Allowed</title>\n"
    "<h1>Method Not Allowed</h1>\n"
    "<p>The method is not allowed for the requested URL.</p>\n"
)

def get_config() -> dict:
    return {"PAGE_SIZE": PAGE_SIZE}

def _jsonify(data, status_code=200):
    body = json.dumps(data, ensure_ascii=True, sort_keys=True)
    return Response(
        content=body + "\n",
        status_code=status_code,
        headers={"Content-Type": "application/json"},
    )

async def _read_json_body(request: Request):
    content_type = request.headers.get("content-type", "")
    mimetype = content_type.split(";", 1)[0].strip().lower()
    if mimetype != "application/json" and not (
        mimetype.startswith("application/") and mimetype.endswith("+json")
    ):
        return None
    try:
        return json.loads(await request.body())
    except ValueError:
        return None

app = FastAPI(docs_url=None, redoc_url=None, openapi_url=None)

@app.exception_handler(StarletteHTTPException)
async def flask_http_exception_handler(request, exc):
    if exc.status_code == 404:
        return HTMLResponse(_FLASK_404_HTML, status_code=404)
    if exc.status_code == 405:
        return HTMLResponse(_FLASK_405_HTML, status_code=405)
    return Response(
        content=json.dumps({"detail": exc.detail}, ensure_ascii=False),
        status_code=exc.status_code,
        headers={"Content-Type": "application/json"},
    )

@app.get("/health")
async def health(config: dict = Depends(get_config)):
    return _jsonify({"status": "ok", "page_size": config["PAGE_SIZE"]})

@app.get("/items")
async def list_items(request: Request, config: dict = Depends(get_config)):
    limit = request.query_params.get("limit")
    if limit is not None:
        try:
            limit = int(limit)
        except ValueError:
            limit = None
    limit = limit or config["PAGE_SIZE"]
    items = list(_ITEMS.values())[:limit]
    return _jsonify({"items": items, "count": len(items)})

@app.post("/items")
async def create_item(request: Request):
    data = await _read_json_body(request)
    if not data:
        return _jsonify({"error": "body must be JSON"}, 400)
    if "name" not in data:
        return _jsonify({"error": "name is required"}, 400)
    if not isinstance(data["name"], str):
        return _jsonify({"error": "name must be a string"}, 400)
    qty = data.get("qty", 0)
    new_id = max(_ITEMS) + 1
    return _jsonify({"id": new_id, "name": data["name"], "qty": qty}, 201)

def _item_id_from_path(item_id: str):
    if re.fullmatch(r"\d+", item_id) is None:
        return None
    return int(item_id)

@app.get("/items/{item_id}")
async def get_item(item_id: str):
    parsed = _item_id_from_path(item_id)
    if parsed is None:
        return HTMLResponse(_FLASK_404_HTML, status_code=404)
    item = _ITEMS.get(parsed)
    if item is None:
        return _jsonify({"error": "item not found"}, 404)
    return _jsonify(item)

@app.delete("/items/{item_id}")
async def delete_item(item_id: str):
    parsed = _item_id_from_path(item_id)
    if parsed is None:
        return HTMLResponse(_FLASK_404_HTML, status_code=404)
    if parsed not in _ITEMS:
        return _jsonify({"error": "item not found"}, 404)
    return _jsonify({"deleted": parsed})
"}"}

{"code": "import json

from fastapi import Depends, FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel


class Settings(BaseModel):
    service_name: str = 'reporting'
    page_size: int = 3
    feature_verbose: bool = True
    max_range_days: int = 30


settings = Settings()


def get_settings() -> Settings:
    return settings


app = FastAPI(docs_url=None, redoc_url=None, openapi_url=None)

_ROWS = [{'id': i, 'value': i * 10} for i in range(1, 11)]


@app.get('/config')
async def show_config(settings: Settings = Depends(get_settings)) -> JSONResponse:
    return JSONResponse(
        content={
            'service': settings.service_name,
            'page_size': settings.page_size,
            'verbose': settings.feature_verbose,
        },
        status_code=200,
    )


@app.get('/rows')
async def rows(
    request: Request,
    settings: Settings = Depends(get_settings),
) -> JSONResponse:
    size = request.query_params.get('size')
    parsed_size = None
    if size is not None:
        try:
            parsed_size = int(size)
        except (TypeError, ValueError):
            parsed_size = None
    page_size = parsed_size or settings.page_size
    page = _ROWS[:page_size]
    payload = {'rows': page}
    if settings.feature_verbose:
        payload['meta'] = {'returned': len(page), 'total': len(_ROWS)}
    return JSONResponse(content=payload, status_code=200)


@app.post('/report')
async def report(
    request: Request,
    settings: Settings = Depends(get_settings),
) -> JSONResponse:
    raw = await request.body()
    content_type = request.headers.get('content-type', '')
    mimetype = content_type.split(';', 1)[0].strip().lower()

    parsed = None
    if mimetype == 'application/json':
        try:
            if raw:
                parsed = json.loads(raw.decode('utf-8'))
            else:
                parsed = None
        except (ValueError, UnicodeDecodeError):
            parsed = None

    data = parsed or {}
    days = data.get('days', 7)
    if not isinstance(days, int):
        return JSONResponse(
            content={'error': 'days must be an integer'},
            status_code=400,
        )
    if days > settings.max_range_days:
        return JSONResponse(
            content={'error': 'range too large', 'max': settings.max_range_days},
            status_code=400,
        )
    return JSONResponse(
        content={'service': settings.service_name, 'days': days},
        status_code=202,
    )
"}

