from fastapi.responses import JSONResponse
from typing import Optional
from urllib.parse import parse_qsl

app = FastAPI(docs_url=None, redoc_url=None, openapi_url=None)

_EVENTS = [{"id": i, "kind": "click"} for i in range(1, 26)]
MAX_PER_PAGE = 10


def _get_int_arg(request: Request, name: str, default: int) -> int:
    values = [
        value
        for key, value in parse_qsl(request.url.query, keep_blank_values=True)
        if key == name
    ]
    if not values:
        return default
    try:
        return int(values[0])
    except ValueError:
        return default


def _json_response(
    content: dict, status_code: int, headers: Optional[dict] = None
) -> JSONResponse:
    response = JSONResponse(content=content, status_code=status_code, headers=headers)
    response.headers["content-type"] = "application/json"
    return response


@app.get("/events")
def events(request: Request):
    page = _get_int_arg(request, "page", 1)
    per_page = _get_int_arg(request, "per_page", 5)

    if page < 1:
        return _json_response({"error": "page must be >= 1"}, 400)

    if per_page > MAX_PER_PAGE:
        per_page = MAX_PER_PAGE

    start = (page - 1) * per_page
    rows = _EVENTS[start : start + per_page]
    total = len(_EVENTS)
    last_page = (total + per_page - 1) // per_page

    headers = {"X-Total-Count": str(total)}
    links = [
        f'</events?page=1&per_page={per_page}>; rel="first"',
        f'</events?page={last_page}&per_page={per_page}>; rel="last"',
    ]
    if page < last_page:
        links.append(f'</events?page={page + 1}&per_page={per_page}>; rel="next"')
    headers["Link"] = ", ".join(links)

    return _json_response(
        {"events": rows, "page": page, "per_page": per_page},
        200,
        headers=headers,
    )
}"}

{"code": "from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse

app = FastAPI(docs_url=None, redoc_url=None, openapi_url=None)

_DOCS = {'d1': {'id': 'd1', 'title': 'spec', 'version': 3}}


def _make_etag(version: int) -> str:
    return 'W/"' + str(version) + '"'


def _is_json_content_type(content_type: str) -> bool:
    mime = content_type.split(';')[0].strip().lower()
    return mime == 'application/json' or mime.endswith('+json')


@app.get('/docs/{doc_id}')
async def get_doc(doc_id: str):
    doc = _DOCS.get(doc_id)
    if doc is None:
        return JSONResponse(status_code=404, content={'error': 'doc not found'})
    response = JSONResponse(status_code=200, content=doc)
    response.headers['ETag'] = _make_etag(doc['version'])
    return response


@app.patch('/docs/{doc_id}')
async def patch_doc(doc_id: str, request: Request):
    doc = _DOCS.get(doc_id)
    if doc is None:
        return JSONResponse(status_code=404, content={'error': 'doc not found'})

    if_match = request.headers.get('If-Match')
    if not if_match:
        return JSONResponse(status_code=428, content={'error': 'If-Match header is required', 'code': 'PRECONDITION_REQUIRED'})
    if if_match != _make_etag(doc['version']):
        return JSONResponse(status_code=409, content={'error': 'version conflict', 'expected': doc['version']})

    data = {}
    raw = await request.body()
    if raw:
        content_type = request.headers.get('content-type', '')
        if _is_json_content_type(content_type):
            try:
                parsed = await request.json()
                data = parsed or {}
            except Exception:
                data = {}

    title = data.get('title')
    if not isinstance(title, str) or not title:
        return JSONResponse(status_code=400, content={'error': 'title must be a non-empty string'})

    new_version = doc['version'] + 1
    updated = {**doc, 'title': title, 'version': new_version}
    response = JSONResponse(status_code=200, content=updated)
    response.headers['ETag'] = _make_etag(new_version)
    return response}"}

{"code":"from fastapi import FastAPI, Query
from fastapi.responses import JSONResponse

app = FastAPI()

_EVENTS = [{"id": i, "kind": "click"} for i in range(1, 26)]
MAX_PER_PAGE = 10

def int_or_default(value: str, default: int) -> int:
    try:
        return int(value)
    except ValueError:
        return default

@app.get("/events")
def events(page: str = Query("1"), per_page: str = Query("5")):
    page = int_or_default(page, 1)
    per_page = int_or_default(per_page, 5)

    if page < 1:
        return JSONResponse(content={"error": "page must be >= 1"}, status_code=400)
    if per_page > MAX_PER_PAGE:
        per_page = MAX_PER_PAGE

    start = (page - 1) * per_page
    rows = _EVENTS[start : start + per_page]
    total = len(_EVENTS)
    last_page = (total + per_page - 1) // per_page

    response = JSONResponse(content={"events": rows, "page": page, "per_page": per_page}, status_code=200)
    response.headers["X-Total-Count"] = str(total)
    links = [
        f'</events?page=1&per_page={per_page}>; rel="first"',
        f'</events?page={last_page}&per_page={per_page}>; rel="last"',
    ]
    if page < last_page:
        links.append(f'</events?page={page + 1}&per_page={per_page}>; rel="next"')
    response.headers["Link"] = ", ".join(links)
    return response
"}

{"code": "import json

from fastapi import FastAPI, Request, Response
from fastapi.responses import RedirectResponse
from starlette.exceptions import HTTPException as StarletteHTTPException


FLASK_NOT_FOUND_HTML = '''<!doctype html>
<html lang=en>
<title>404 Not Found</title>
<h1>Not Found</h1>
<p>The requested URL was not found on the server. If you entered the URL manually please check your spelling and try again.</p>
'''

FLASK_METHOD_NOT_ALLOWED_HTML = '''<!doctype html>
<html lang=en>
<title>405 Method Not Allowed</title>
<h1>Method Not Allowed</h1>
<p>The method is not allowed for the requested URL.</p>
'''


def flask_json(payload):
    body = (json.dumps(payload, separators=(',', ':'), ensure_ascii=True, sort_keys=True) + chr(10)).encode('utf-8')
    return Response(content=body, media_type='application/json', headers={'Content-Type': 'application/json'})


app = FastAPI(docs_url=None, redoc_url=None, openapi_url=None)
app.router.redirect_slashes = False


@app.exception_handler(StarletteHTTPException)
async def http_exception_handler(request: Request, exc: StarletteHTTPException):
    if exc.status_code == 404:
        return Response(content=FLASK_NOT_FOUND_HTML, status_code=404, media_type='text/html')
    if exc.status_code == 405:
        return Response(
            content=FLASK_METHOD_NOT_ALLOWED_HTML,
            status_code=405,
            headers=exc.headers or {},
            media_type='text/html',
        )
    return Response(
        content=json.dumps({'detail': exc.detail}),
        status_code=exc.status_code,
        media_type='application/json',
    )


@app.get('/reports/')
def list_reports():
    return flask_json({'reports': ['daily', 'weekly']})


@app.api_route('/reports', methods=['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD', 'OPTIONS', 'TRACE'], include_in_schema=False)
def redirect_reports(request: Request):
    location = '/reports/'
    if request.url.query:
        location = location + '?' + request.url.query
    return RedirectResponse(url=location, status_code=308)


@app.get('/status')
def status():
    return flask_json({'status': 'up'})


@app.get('/jobs')
def jobs():
    return flask_json({'jobs': []})


@app.get('/jobs/')
def jobs_trailing():
    return flask_json({'jobs': []})


@app.get('/queue/{name}')
def queue(name: str):
    return flask_json({'queue': name, 'depth': 0})
"}

{"code":"import json
from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse

app = FastAPI()

_DOCS = {"d1": {"id": "d1", "title": "spec", "version": 3}}

def _etag(version: int) -> str:
    return f'W/"{version}"'

@app.get("/docs/{doc_id}")
async def get_doc(doc_id: str):
    doc = _DOCS.get(doc_id)
    if doc is None:
        return JSONResponse(status_code=404, content={"error": "doc not found"})
    return JSONResponse(status_code=200, content=doc, headers={"ETag": _etag(doc["version"])})

@app.patch("/docs/{doc_id}")
async def patch_doc(doc_id: str, request: Request):
    doc = _DOCS.get(doc_id)
    if doc is None:
        return JSONResponse(status_code=404, content={"error": "doc not found"})

    if_match = request.headers.get("If-Match")
    if not if_match:
        return JSONResponse(
            status_code=428,
            content={"error": "If-Match header is required", "code": "PRECONDITION_REQUIRED"},
        )
    if if_match != _etag(doc["version"]):
        return JSONResponse(
            status_code=409,
            content={"error": "version conflict", "expected": doc["version"]},
        )

    body = await request.body()
    data = {}
    if body:
        content_type = request.headers.get("content-type")
        if content_type:
            mimetype = content_type.split(";")[0].strip().lower()
            if mimetype == "application/json" or mimetype.endswith("+json"):
                try:
                    parsed = json.loads(body)
                    if isinstance(parsed, dict):
                        data = parsed
                except Exception:
                    data = {}

    title = data.get("title")
    if not isinstance(title, str) or not title:
        return JSONResponse(
            status_code=400,
            content={"error": "title must be a non-empty string"},
        )

    new_version = doc["version"] + 1
    updated_doc = {**doc, "title": title, "version": new_version}
    return JSONResponse(
        status_code=200,
        content=updated_doc,
        headers={"ETag": _etag(new_version)},
    )"}

